-- =============================================================================
-- Smart HAS - Fase 6 | 01_ddl_tabelas.sql
-- Modelo fisico Oracle (compativel com Oracle 19c+ / 21c XE / 23ai Free).
--
-- Convencoes:
--   * Prefixo SHAS_ em todas as tabelas (evita colisao em schema compartilhado,
--     ex.: servidor Oracle da FIAP).
--   * PK surrogate com IDENTITY (GENERATED BY DEFAULT permite carga com id fixo).
--   * Constraints nomeadas: PK_, FK_, UK_, CK_; indices: IX_.
--   * Dominios fechados validados por CHECK (espelham os enums do back-end Java).
--   * Booleanos como NUMBER(1) 0/1 (Oracle < 23 nao possui BOOLEAN em tabela).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- SHAS_USUARIO: operadores/administradores da plataforma (login da API).
-- -----------------------------------------------------------------------------
CREATE TABLE shas_usuario (
    id_usuario   NUMBER(10)    GENERATED BY DEFAULT AS IDENTITY,
    nome         VARCHAR2(100) NOT NULL,
    username     VARCHAR2(50)  NOT NULL,
    email        VARCHAR2(120) NOT NULL,
    senha_hash   VARCHAR2(100) NOT NULL,
    perfil       VARCHAR2(20)  NOT NULL,
    dt_criacao   TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_shas_usuario          PRIMARY KEY (id_usuario),
    CONSTRAINT uk_shas_usuario_username UNIQUE (username),
    CONSTRAINT uk_shas_usuario_email    UNIQUE (email),
    CONSTRAINT ck_shas_usuario_perfil   CHECK (perfil IN ('ADMIN', 'OPERATOR'))
);

COMMENT ON TABLE  shas_usuario            IS 'Usuarios da plataforma Smart HAS (autenticacao JWT na API).';
COMMENT ON COLUMN shas_usuario.senha_hash IS 'Senha em BCrypt - nunca armazenar em texto puro.';
COMMENT ON COLUMN shas_usuario.perfil     IS 'ADMIN = acesso total | OPERATOR = leitura + alertas + leituras.';

-- -----------------------------------------------------------------------------
-- SHAS_SENSOR: dispositivos IoT de monitoramento urbano.
-- limite_alerta / limite_critico parametrizam a classificacao das leituras
-- (regra aplicada em FN_CLASSIFICAR_LEITURA e PRC_REGISTRAR_LEITURA).
-- -----------------------------------------------------------------------------
CREATE TABLE shas_sensor (
    id_sensor       NUMBER(10)    GENERATED BY DEFAULT AS IDENTITY,
    nome            VARCHAR2(100) NOT NULL,
    tipo            VARCHAR2(50)  NOT NULL,
    status          VARCHAR2(20)  DEFAULT 'ONLINE' NOT NULL,
    localizacao     VARCHAR2(150) NOT NULL,
    valor_atual     NUMBER(12, 2),
    unidade         VARCHAR2(20),
    latitude        NUMBER(9, 6),
    longitude       NUMBER(9, 6),
    limite_alerta   NUMBER(12, 2),
    limite_critico  NUMBER(12, 2),
    id_responsavel  NUMBER(10),
    dt_atualizacao  TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_shas_sensor         PRIMARY KEY (id_sensor),
    CONSTRAINT fk_shas_sensor_usuario FOREIGN KEY (id_responsavel)
        REFERENCES shas_usuario (id_usuario) ON DELETE SET NULL,
    CONSTRAINT ck_shas_sensor_status  CHECK (status IN ('ONLINE', 'WARNING', 'OFFLINE')),
    CONSTRAINT ck_shas_sensor_limites CHECK (
        limite_alerta IS NULL OR limite_critico IS NULL OR limite_critico >= limite_alerta),
    CONSTRAINT ck_shas_sensor_lat     CHECK (latitude  BETWEEN -90  AND 90),
    CONSTRAINT ck_shas_sensor_lon     CHECK (longitude BETWEEN -180 AND 180)
);

CREATE INDEX ix_shas_sensor_responsavel ON shas_sensor (id_responsavel);
CREATE INDEX ix_shas_sensor_status      ON shas_sensor (status);

COMMENT ON TABLE  shas_sensor                IS 'Sensores IoT monitorados pelo Smart HAS.';
COMMENT ON COLUMN shas_sensor.limite_alerta  IS 'Valor a partir do qual a leitura e classificada como ALERTA.';
COMMENT ON COLUMN shas_sensor.limite_critico IS 'Valor a partir do qual a leitura e classificada como CRITICA.';
COMMENT ON COLUMN shas_sensor.id_responsavel IS 'Usuario responsavel pela manutencao do sensor.';

-- -----------------------------------------------------------------------------
-- SHAS_LEITURA: historico (serie temporal) de medicoes de cada sensor.
-- -----------------------------------------------------------------------------
CREATE TABLE shas_leitura (
    id_leitura     NUMBER(12)   GENERATED BY DEFAULT AS IDENTITY,
    id_sensor      NUMBER(10)   NOT NULL,
    valor          NUMBER(12, 2) NOT NULL,
    classificacao  VARCHAR2(10) NOT NULL,
    dt_leitura     TIMESTAMP    DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_shas_leitura        PRIMARY KEY (id_leitura),
    CONSTRAINT fk_shas_leitura_sensor FOREIGN KEY (id_sensor)
        REFERENCES shas_sensor (id_sensor) ON DELETE CASCADE,
    CONSTRAINT ck_shas_leitura_class  CHECK (classificacao IN ('NORMAL', 'ALERTA', 'CRITICA'))
);

-- Indice composto: toda consulta analitica filtra por sensor + janela de tempo.
CREATE INDEX ix_shas_leitura_sensor_dt ON shas_leitura (id_sensor, dt_leitura);

COMMENT ON TABLE shas_leitura IS 'Serie historica de leituras dos sensores (dados de telemetria).';

-- -----------------------------------------------------------------------------
-- SHAS_ALERTA: ocorrencias manuais (operador) ou automaticas (PL/SQL).
-- -----------------------------------------------------------------------------
CREATE TABLE shas_alerta (
    id_alerta     NUMBER(10)     GENERATED BY DEFAULT AS IDENTITY,
    titulo        VARCHAR2(150)  NOT NULL,
    descricao     VARCHAR2(1000),
    severidade    VARCHAR2(10)   NOT NULL,
    localizacao   VARCHAR2(150)  NOT NULL,
    origem        VARCHAR2(10)   DEFAULT 'MANUAL' NOT NULL,
    id_sensor     NUMBER(10),
    id_leitura    NUMBER(12),
    resolvido     NUMBER(1)      DEFAULT 0 NOT NULL,
    dt_criacao    TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    dt_resolucao  TIMESTAMP,
    CONSTRAINT pk_shas_alerta          PRIMARY KEY (id_alerta),
    CONSTRAINT fk_shas_alerta_sensor   FOREIGN KEY (id_sensor)
        REFERENCES shas_sensor (id_sensor) ON DELETE SET NULL,
    CONSTRAINT fk_shas_alerta_leitura  FOREIGN KEY (id_leitura)
        REFERENCES shas_leitura (id_leitura) ON DELETE SET NULL,
    CONSTRAINT ck_shas_alerta_sev      CHECK (severidade IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_shas_alerta_origem   CHECK (origem IN ('MANUAL', 'AUTOMATICO')),
    CONSTRAINT ck_shas_alerta_resolv   CHECK (resolvido IN (0, 1)),
    CONSTRAINT ck_shas_alerta_resol    CHECK (resolvido = 1 OR dt_resolucao IS NULL)
);

CREATE INDEX ix_shas_alerta_sensor   ON shas_alerta (id_sensor, resolvido);
CREATE INDEX ix_shas_alerta_leitura  ON shas_alerta (id_leitura);
CREATE INDEX ix_shas_alerta_local    ON shas_alerta (localizacao, resolvido);

COMMENT ON TABLE  shas_alerta        IS 'Alertas de monitoramento (manuais ou gerados automaticamente pelo banco).';
COMMENT ON COLUMN shas_alerta.origem IS 'MANUAL = criado por usuario | AUTOMATICO = gerado por PL/SQL.';

-- -----------------------------------------------------------------------------
-- SHAS_RELATORIO_DIARIO: consolidacao diaria por sensor, alimentada pela
-- procedure PRC_GERAR_RELATORIO_DIARIO (rotina batch executada no banco).
-- -----------------------------------------------------------------------------
CREATE TABLE shas_relatorio_diario (
    id_relatorio    NUMBER(12)    GENERATED BY DEFAULT AS IDENTITY,
    id_sensor       NUMBER(10)    NOT NULL,
    dt_referencia   DATE          NOT NULL,
    qtd_leituras    NUMBER(10)    NOT NULL,
    qtd_alertas     NUMBER(10)    NOT NULL,
    qtd_criticas    NUMBER(10)    NOT NULL,
    valor_minimo    NUMBER(12, 2),
    valor_medio     NUMBER(12, 2),
    valor_maximo    NUMBER(12, 2),
    conformidade    NUMBER(5, 2),
    resumo          VARCHAR2(400),
    dt_geracao      TIMESTAMP     DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_shas_relatorio        PRIMARY KEY (id_relatorio),
    CONSTRAINT fk_shas_relatorio_sensor FOREIGN KEY (id_sensor)
        REFERENCES shas_sensor (id_sensor) ON DELETE CASCADE,
    CONSTRAINT uk_shas_relatorio_dia    UNIQUE (id_sensor, dt_referencia),
    CONSTRAINT ck_shas_relatorio_conf   CHECK (conformidade BETWEEN 0 AND 100)
);

COMMENT ON TABLE  shas_relatorio_diario              IS 'Consolidado diario de leituras por sensor (gerado via PL/SQL).';
COMMENT ON COLUMN shas_relatorio_diario.conformidade IS 'Percentual de leituras NORMAIS no dia (0-100).';
COMMENT ON COLUMN shas_relatorio_diario.qtd_alertas  IS 'Leituras classificadas como ALERTA no dia.';
COMMENT ON COLUMN shas_relatorio_diario.qtd_criticas IS 'Leituras classificadas como CRITICA no dia.';

-- -----------------------------------------------------------------------------
-- SHAS_LOG_EXECUCAO: trilha de auditoria das rotinas PL/SQL (governanca).
-- Gravada via PRAGMA AUTONOMOUS_TRANSACTION: persiste mesmo com ROLLBACK.
-- -----------------------------------------------------------------------------
CREATE TABLE shas_log_execucao (
    id_log    NUMBER(12)     GENERATED BY DEFAULT AS IDENTITY,
    rotina    VARCHAR2(60)   NOT NULL,
    nivel     VARCHAR2(10)   NOT NULL,
    mensagem  VARCHAR2(4000),
    dt_log    TIMESTAMP      DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_shas_log       PRIMARY KEY (id_log),
    CONSTRAINT ck_shas_log_nivel CHECK (nivel IN ('INFO', 'WARN', 'ERROR'))
);

CREATE INDEX ix_shas_log_rotina_dt ON shas_log_execucao (rotina, dt_log);

COMMENT ON TABLE shas_log_execucao IS 'Log de execucao e erros das procedures/functions do Smart HAS.';
